--
-- Table structure for table `ordenes_trabajo`
--

DROP TABLE IF EXISTS `ordenes_trabajo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ordenes_trabajo` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `numero_ot` bigint unsigned NOT NULL,
  `area` enum('LYP','MECANICA') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LYP',
  `id_vehiculo` bigint unsigned NOT NULL,
  `id_cliente_persona` bigint unsigned DEFAULT NULL,
  `id_empresa_cliente` bigint unsigned NOT NULL,
  `km_ingreso` int unsigned NOT NULL DEFAULT '0',
  `referencia_forc` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `llaves_entregadas` tinyint(1) NOT NULL DEFAULT '0',
  `documentos_entregados` tinyint(1) NOT NULL DEFAULT '0',
  `ingreso_grua` tinyint(1) NOT NULL DEFAULT '0',
  `nivel_combustible` tinyint unsigned NOT NULL DEFAULT '0',
  `estado_proceso` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PTE_COTIZACION',
  `estado_semaforo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SIN_FECHA',
  `tg` enum('Leve','Medio','Fuerte') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dr` tinyint unsigned DEFAULT NULL,
  `ha` decimal(8,2) DEFAULT NULL,
  `num_piezas` decimal(5,1) NOT NULL DEFAULT '0.0',
  `fecha_ingreso` date NOT NULL,
  `fecha_cotizacion` date DEFAULT NULL,
  `fecha_autorizacion` date DEFAULT NULL,
  `fecha_llegada_ultimo_rto` date DEFAULT NULL,
  `fecha_inicio_proceso` date DEFAULT NULL,
  `fecha_terminacion` date DEFAULT NULL,
  `fecha_entrega_cliente` date DEFAULT NULL,
  `salida_estimada` date DEFAULT NULL,
  `valor_mo` decimal(12,2) NOT NULL DEFAULT '0.00',
  `valor_rto` decimal(12,2) NOT NULL DEFAULT '0.00',
  `valor_insumos_pint` decimal(12,2) NOT NULL DEFAULT '0.00',
  `valor_terceros` decimal(12,2) NOT NULL DEFAULT '0.00',
  `valor_op` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `pasado_a_facturar` tinyint(1) NOT NULL DEFAULT '0',
  `costo_mo` decimal(12,2) NOT NULL DEFAULT '0.00',
  `costo_rto` decimal(12,2) NOT NULL DEFAULT '0.00',
  `costo_insumos` decimal(12,2) NOT NULL DEFAULT '0.00',
  `costo_total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `tecnico_lat` bigint unsigned DEFAULT NULL,
  `tecnico_prep` bigint unsigned DEFAULT NULL,
  `tecnico_pint` bigint unsigned DEFAULT NULL,
  `tecnico_mec` bigint unsigned DEFAULT NULL,
  `tecnico_elec` bigint unsigned DEFAULT NULL,
  `tiene_scanner` tinyint(1) NOT NULL DEFAULT '0',
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `creado_por` bigint unsigned NOT NULL,
  `actualizado_por` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ordenes_trabajo_numero_ot_unique` (`numero_ot`),
  KEY `ordenes_trabajo_id_vehiculo_foreign` (`id_vehiculo`),
  KEY `ordenes_trabajo_id_cliente_persona_foreign` (`id_cliente_persona`),
  KEY `ordenes_trabajo_id_empresa_cliente_foreign` (`id_empresa_cliente`),
  KEY `ordenes_trabajo_tecnico_lat_foreign` (`tecnico_lat`),
  KEY `ordenes_trabajo_tecnico_prep_foreign` (`tecnico_prep`),
  KEY `ordenes_trabajo_tecnico_pint_foreign` (`tecnico_pint`),
  KEY `ordenes_trabajo_tecnico_mec_foreign` (`tecnico_mec`),
  KEY `ordenes_trabajo_tecnico_elec_foreign` (`tecnico_elec`),
  KEY `ordenes_trabajo_creado_por_foreign` (`creado_por`),
  KEY `ordenes_trabajo_actualizado_por_foreign` (`actualizado_por`),
  CONSTRAINT `ordenes_trabajo_actualizado_por_foreign` FOREIGN KEY (`actualizado_por`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ordenes_trabajo_creado_por_foreign` FOREIGN KEY (`creado_por`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ordenes_trabajo_id_cliente_persona_foreign` FOREIGN KEY (`id_cliente_persona`) REFERENCES `clientes_persona` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ordenes_trabajo_id_empresa_cliente_foreign` FOREIGN KEY (`id_empresa_cliente`) REFERENCES `empresas_cliente` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ordenes_trabajo_id_vehiculo_foreign` FOREIGN KEY (`id_vehiculo`) REFERENCES `vehiculos` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ordenes_trabajo_tecnico_elec_foreign` FOREIGN KEY (`tecnico_elec`) REFERENCES `tecnicos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ordenes_trabajo_tecnico_lat_foreign` FOREIGN KEY (`tecnico_lat`) REFERENCES `tecnicos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ordenes_trabajo_tecnico_mec_foreign` FOREIGN KEY (`tecnico_mec`) REFERENCES `tecnicos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ordenes_trabajo_tecnico_pint_foreign` FOREIGN KEY (`tecnico_pint`) REFERENCES `tecnicos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ordenes_trabajo_tecnico_prep_foreign` FOREIGN KEY (`tecnico_prep`) REFERENCES `tecnicos` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=525 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

