DROP TABLE IF EXISTS `pagos_tecnicos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pagos_tecnicos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `id_tecnico` bigint unsigned NOT NULL,
  `id_user` bigint unsigned NOT NULL,
  `id_ot` bigint unsigned DEFAULT NULL,
  `anio` smallint unsigned NOT NULL,
  `mes` tinyint unsigned NOT NULL,
  `monto` decimal(12,2) NOT NULL,
  `tipo` enum('ABONO','PAGO_FINAL','ANTICIPO') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ABONO',
  `concepto` text COLLATE utf8mb4_unicode_ci,
  `fecha_pago` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pagos_tecnicos_id_tecnico_foreign` (`id_tecnico`),
  KEY `pagos_tecnicos_id_user_foreign` (`id_user`),
  KEY `pagos_tecnicos_id_ot_foreign` (`id_ot`),
  CONSTRAINT `pagos_tecnicos_id_ot_foreign` FOREIGN KEY (`id_ot`) REFERENCES `ordenes_trabajo` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pagos_tecnicos_id_tecnico_foreign` FOREIGN KEY (`id_tecnico`) REFERENCES `tecnicos` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `pagos_tecnicos_id_user_foreign` FOREIGN KEY (`id_user`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
