--
-- Table structure for table `vehiculos`
--

DROP TABLE IF EXISTS `vehiculos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehiculos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `placa` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_marca` bigint unsigned NOT NULL,
  `id_modelo` bigint unsigned DEFAULT NULL,
  `color` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `anio` smallint unsigned DEFAULT NULL,
  `id_cliente_persona` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vehiculos_placa_unique` (`placa`),
  KEY `vehiculos_id_marca_foreign` (`id_marca`),
  KEY `vehiculos_id_modelo_foreign` (`id_modelo`),
  KEY `vehiculos_id_cliente_persona_foreign` (`id_cliente_persona`),
  CONSTRAINT `vehiculos_id_cliente_persona_foreign` FOREIGN KEY (`id_cliente_persona`) REFERENCES `clientes_persona` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vehiculos_id_marca_foreign` FOREIGN KEY (`id_marca`) REFERENCES `marcas_vehiculo` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `vehiculos_id_modelo_foreign` FOREIGN KEY (`id_modelo`) REFERENCES `modelos_vehiculo` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=438 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

